def can_3_partition(m):
    """
    Checks if {1, 2, ..., m} can be partitioned into 3 non-empty subsets 
    each summing to T = m(m+1)/6.
    """
    S_total = m * (m + 1) // 2
    if S_total % 3 != 0:
        return False
    T = S_total // 3

    elements = list(range(1, m + 1))

    # Targets for the three buckets (X, Y, Z)
    targets = [T, T, T]

    def backtrack(item_index, current_sums, counts):
        if item_index == m:
            # Check if all targets are met and all sets are non-empty
            return current_sums[0] == T and current_sums[1] == T and current_sums[2] == T and all(c > 0 for c in counts)

        element = elements[item_index]

        # Try placing the element in each of the three buckets
        for i in range(3):
            if current_sums[i] + element <= T:

                # Optimization to handle symmetrical branches:
                # If the current bucket is empty, we only assign the element 
                # to this bucket if it is the first empty bucket encountered.
                if current_sums[i] == 0:
                    is_first_empty = True
                    for j in range(i):
                        if current_sums[j] == 0:
                            is_first_empty = False
                            break
                    if not is_first_empty:
                        continue

                new_sums = list(current_sums)
                new_counts = list(counts)
                new_sums[i] += element
                new_counts[i] += 1

                if backtrack(item_index + 1, new_sums, new_counts):
                    return True
        return False

    # Start search
    return backtrack(0, [0, 0, 0], [0, 0, 0])

